/*\n  # Create Newsletter Leads System\n\n  ## Overview\n  Creates a completely separate newsletter leads system independent from the regular\n  leads tracking. This allows dedicated management of email marketing contacts with\n  their own data structure and workflows.\n\n  ## New Tables\n\n  ### newsletter_leads\n    - `id` (uuid, primary key) - Unique identifier for each newsletter lead\n    - `name` (text) - Full name or company name\n    - `email` (text, required, unique) - Email address for the contact\n    - `title` (text) - Job title or role\n    - `attraction_type` (text) - Type of attraction/business\n    - `note` (text) - Notes about the contact\n    - `telephone` (text) - Optional phone number\n    - `website` (text) - Website URL\n    - `social_media` (text) - Social media handles/links\n    - `status` (text) - Lead status (new, contacted, interested, etc.)\n    - `opt_in` (boolean, default true) - Email marketing consent\n    - `unsubscribed` (boolean, default false) - Unsubscribe status\n    - `created_at` (timestamptz) - Record creation timestamp\n    - `updated_at` (timestamptz) - Last update timestamp\n    - `user_id` (uuid, foreign key) - Owner of this newsletter lead\n\n  ## Security\n    - Enable RLS on newsletter_leads table\n    - Users can only view/manage their own newsletter leads\n    - Proper insert, select, update, and delete policies\n\n  ## Important Notes\n  - This table is completely separate from the main leads table\n  - Designed specifically for email marketing campaigns\n  - Includes all fields needed for newsletter management\n  - Supports both manual entry and CSV import\n*/\n\n-- Create newsletter_leads table\nCREATE TABLE IF NOT EXISTS newsletter_leads (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  name text NOT NULL,\n  email text NOT NULL,\n  title text,\n  attraction_type text,\n  note text,\n  telephone text,\n  website text,\n  social_media text,\n  status text DEFAULT 'new' NOT NULL,\n  opt_in boolean DEFAULT true NOT NULL,\n  unsubscribed boolean DEFAULT false NOT NULL,\n  created_at timestamptz DEFAULT now() NOT NULL,\n  updated_at timestamptz DEFAULT now() NOT NULL,\n  user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL\n);
\n\n-- Create index on email for faster lookups\nCREATE INDEX IF NOT EXISTS idx_newsletter_leads_email ON newsletter_leads(email);
\n\n-- Create index on user_id for RLS performance\nCREATE INDEX IF NOT EXISTS idx_newsletter_leads_user_id ON newsletter_leads(user_id);
\n\n-- Create index on status for filtering\nCREATE INDEX IF NOT EXISTS idx_newsletter_leads_status ON newsletter_leads(status);
\n\n-- Add unique constraint on email per user (same email can exist for different users)\nCREATE UNIQUE INDEX IF NOT EXISTS idx_newsletter_leads_user_email ON newsletter_leads(user_id, email);
\n\n-- Enable Row Level Security\nALTER TABLE newsletter_leads ENABLE ROW LEVEL SECURITY;
\n\n-- Policy: Users can view their own newsletter leads\nCREATE POLICY "Users can view own newsletter leads"\n  ON newsletter_leads\n  FOR SELECT\n  TO authenticated\n  USING (auth.uid() = user_id);
\n\n-- Policy: Users can insert their own newsletter leads\nCREATE POLICY "Users can insert own newsletter leads"\n  ON newsletter_leads\n  FOR INSERT\n  TO authenticated\n  WITH CHECK (auth.uid() = user_id);
\n\n-- Policy: Users can update their own newsletter leads\nCREATE POLICY "Users can update own newsletter leads"\n  ON newsletter_leads\n  FOR UPDATE\n  TO authenticated\n  USING (auth.uid() = user_id)\n  WITH CHECK (auth.uid() = user_id);
\n\n-- Policy: Users can delete their own newsletter leads\nCREATE POLICY "Users can delete own newsletter leads"\n  ON newsletter_leads\n  FOR DELETE\n  TO authenticated\n  USING (auth.uid() = user_id);
\n\n-- Create function to update updated_at timestamp\nCREATE OR REPLACE FUNCTION update_newsletter_leads_updated_at()\nRETURNS TRIGGER AS $$\nBEGIN\n  NEW.updated_at = now();
\n  RETURN NEW;
\nEND;
\n$$ LANGUAGE plpgsql;
\n\n-- Create trigger to automatically update updated_at\nDROP TRIGGER IF EXISTS trigger_update_newsletter_leads_updated_at ON newsletter_leads;
\nCREATE TRIGGER trigger_update_newsletter_leads_updated_at\n  BEFORE UPDATE ON newsletter_leads\n  FOR EACH ROW\n  EXECUTE FUNCTION update_newsletter_leads_updated_at();
\n;
